    private static void ensureSearchField(GuiBase screen, ConfigScreenState state) {
        if (is26x()) {
            return;
        }

        ConfigLayout layout = state.layout;
        int x = layout.sidebarX + layout.sidebarW + 17;
        int y = layout.panelY + 4;
        WidgetDropDownList<ModInfo> switcher = screen instanceof GuiConfigsBase configs
                ? ((GuiConfigsBaseAccessor) configs).malilibui$getModSwitchWidget() : null;
        int right = switcher != null ? switcher.getX() - 6
                : layout.contentX + layout.contentW - 6;
        int w = Math.max(80, right - x);

        if (state.searchField == null) {
            GuiTextFieldGeneric field = new GuiTextFieldGeneric(x, y, w, 18, screen.getFont());
            field.setMaxLength(64);
            field.setFocused(false);
            state.searchActive = false;
            state.searchField = field;
            ((GuiBaseAccessor) screen).malilibui$getTextFields().add(new TextFieldWrapper<>(field, null));
        } else {
            state.searchField.setX(x);
            state.searchField.setY(y);
            state.searchField.setWidth(w);
            state.searchField.setHeight(18);
        }

        if (screen instanceof fi.dy.masa.malilib.gui.GuiListBase<?, ?, ?> listBase) {
            fi.dy.masa.malilib.gui.widgets.WidgetListBase<?, ?> listWidget =
                    ((com.github.bunnyi116.malilibui.mixin.accessor.GuiListBaseAccessor) listBase)
                            .malilibui$getListWidget();

            if (listWidget != null && listWidget.getSearchBarWidget() != null) {
                // 閸掓銆冮崘鍛畱閹兼粎鍌ㄥ鍡楀嚒鐞氼偊銆婇弽蹇撳絿娴狅綇绱濈粔璇插毉鐏炲繐绠烽柆鍨帳闁插秴顦查妴?
                fi.dy.masa.malilib.gui.widgets.WidgetSearchBar bar = listWidget.getSearchBarWidget();
                GuiTextFieldGeneric nativeBox =
                        ((com.github.bunnyi116.malilibui.mixin.accessor.WidgetSearchBarAccessor) bar)
                                .malilibui$getSearchBox();
                state.nativeSearchBox = nativeBox;
                bar.setSearchOpen(true);
                nativeBox.setFocused(false);

                boolean changed = !state.searchField.getValue().equals(nativeBox.getValue());
                nativeBox.setValue(state.searchField.getValue());

                if (changed) {
                    state.lastNativeSearch = state.searchField.getValue();
                    ((com.github.bunnyi116.malilibui.mixin.accessor.WidgetListBaseAccessor) listWidget)
                            .malilibui$refreshBrowserEntries();
                }
            }
        }

        String text = state.searchField.getValue();

        if (!text.equals(state.searchQuery)) {
            state.searchQuery = text;
        }
    }

    private static void ensureModTree(GuiBase screen, ConfigScreenState state) {
        if (is26x()) {
            return;
        }

        ConfigLayout layout = state.layout;
        state.treeRows.clear();

        String currentModId = getModId(screen);

        if (!state.autoExpanded) {
            EXPANDED_MODS.add(currentModId);
            state.autoExpanded = true;
        }

        final int modRowH = 24;
        final int tabRowH = 14;
        int bottom = layout.listY + layout.listH + 6;
        java.util.List<ModTree.ModEntry> entries = ModTree.snapshot();

        int totalH = 0;

        for (ModTree.ModEntry entry : entries) {
            totalH += modRowH + 6;

            if (EXPANDED_MODS.contains(entry.info().modId())) {
                totalH += entry.tabs().size() * tabRowH;
            }
        }

        int viewH = bottom - layout.navY;
        state.treeScroll = Math.max(0, Math.min(state.treeScroll, Math.max(0, totalH - viewH)));
        state.treeContentH = totalH;

        int y = layout.navY - state.treeScroll;

        for (ModTree.ModEntry entry : entries) {
            if (y >= bottom) {
                break;
            }

            String modId = entry.info().modId();
            boolean current = modId.equals(currentModId);
            boolean expanded = EXPANDED_MODS.contains(modId);
            String name = UiTheme.trim(screen.getFont(), entry.info().modName(), layout.navW - 30);
            String version = net.fabricmc.loader.api.FabricLoader.getInstance().getModContainer(modId)
                    .map(c -> c.getMetadata().getVersion().getFriendlyString()).orElse("");

            state.treeRows.add(new ConfigScreenState.TreeRow(layout.navX, y, layout.navW, modRowH,
                    name, version, current, false, modId, -1));
            y += modRowH;

            if (expanded) {
                java.util.List<String> tabs = entry.tabs();

                if (current && !state.navButtons.isEmpty()) {
                    tabs = new java.util.ArrayList<>();

                    for (ButtonBase nav : state.navButtons) {
                        tabs.add(((ButtonBaseAccessor) nav).malilibui$getDisplayString());
                    }
                }

                for (int tabIndex = 0; tabIndex < tabs.size(); tabIndex++) {
                    if (y >= bottom) {
                        break;
                    }

                    String tabName = UiTheme.trim(screen.getFont(), tabs.get(tabIndex), layout.navW - 42);
                    state.treeRows.add(new ConfigScreenState.TreeRow(layout.navX + 8, y,
                            layout.navW - 8, tabRowH, tabName, "",
                            current && tabIndex == state.selectedTabIndex, true, modId, tabIndex));
                    y += tabRowH;
                }
            }

            y += 6;
        }

        for (ButtonBase nav : state.navButtons) {
            nav.setPosition(-1000, -1000);
        }
    }

    /** Handles clicks on the custom tree without ButtonGeneric list churn. */
    public static boolean onTreeClick(GuiBase screen, double mouseX, double mouseY, int mouseButton) {
        if (is26x() || !hasLayout(screen)) {
            return false;
        }

        ConfigScreenState state = stateFor(screen);
        ConfigLayout layout = state.layout;

        if (mouseX < layout.sidebarX || mouseX > layout.sidebarX + layout.sidebarW ||
                mouseY < layout.navY || mouseY > layout.sidebarY + layout.sidebarH) {
            return false;
        }

        String currentModId = getModId(screen);

        for (ConfigScreenState.TreeRow row : state.treeRows) {
            if (!row.contains(mouseX, mouseY)) {
                continue;
            }

            if (row.tab()) {
                if (row.modId().equals(currentModId) && row.tabIndex() < state.navButtons.size()) {
                    state.selectedTabIndex = row.tabIndex();
                    ButtonBase nativeButton = state.navButtons.get(row.tabIndex());
                    var listener = ((ButtonBaseAccessor) nativeButton).malilibui$getActionListener();

                    if (listener != null) {
                        listener.actionPerformedWithButton(nativeButton, 0);
                    }
                } else {
                    ModTree.ModEntry entry = ModTree.snapshot().stream()
                            .filter(e -> e.info().modId().equals(row.modId())).findFirst().orElse(null);

                    if (entry != null) {
                        GuiBase target = entry.info().configScreenSupplier().get();

                        if (target != null) {
                            PENDING_TAB.put(target, row.tabIndex());
                            GuiBase.openGui(target);
                        }
                    }
                }

                return true;
            }

            if (row.modId().equals(currentModId)) {
                if (!EXPANDED_MODS.remove(row.modId())) {
                    EXPANDED_MODS.add(row.modId());
                }
            } else {
                EXPANDED_MODS.add(row.modId());
                ModTree.ModEntry entry = ModTree.snapshot().stream()
                        .filter(e -> e.info().modId().equals(row.modId())).findFirst().orElse(null);

                if (entry != null) {
                    GuiBase target = entry.info().configScreenSupplier().get();

                    if (target != null) {
                        GuiBase.openGui(target);
                    }
                }
            }

            return true;
        }

        return true;
    }
