    private static boolean isTabButton(ButtonBase button) {
        int y = button.getY();

        return y >= 0 && y <= TAB_STRIP_MAX_Y &&
                button.getHeight() > 0 && button.getHeight() <= TAB_MAX_HEIGHT &&
                button.getWidth() > 0;
    }

