    /** 2.0 闂傚倸鍊峰ù鍥敋瑜庨〃銉╁传閵壯咁槸婵犵數濮撮崑鍡涙倿娴犲鐓犲┑顔藉姇閳ь剚顨堟竟鏇㈡嚍閵夛箑寮垮┑鈽嗗灡鐎笛呮兜妤ｅ啯鐓熼柕鍫濐槺閻ｆ椽鏌熼娆炬綈婵炵⒈浜獮宥夘敊閹锋﹩鍙冨铏圭磼濡崵鍙嗛梺鍛婅壘椤戝顕ｉ弻銉晢闁告洦鍓涢崢閬嶆⒑閸濆嫭鍌ㄩ柛鏂跨焸閻涱喖顫滈埀顒勫蓟閿濆绠婚柤纰卞墰閻涖垹鈹戦纭锋敾婵＄偠妫勯悾鐑筋敃閿曗偓缁€瀣亜閹炬剚妾х紓宥勭窔瀵鈽夐姀鐘靛幐婵炴挻鑹鹃敃銈嗘叏濞戞ǚ鏀介柍銉ュ暱缁狙囨煕閺冣偓閻熴儵顢氶敐澶婄濞达絿鎳撻悵浼存⒑閸涘﹥瀵欓柛鎰ㄦ櫇娴滎亪姊绘担鑺ャ€冪紒鈧担铏圭煋闁荤喐澹嗛弳锕傛煟閺冨倵鎷￠柡浣告喘閺岋絽顫滈埀顒€顭囪閺侇噣骞掑Δ浣叉嫽婵炶揪缍€濡嫰宕ヨぐ鎺撶厱閻庯綆鍓欐禒褏绱掗鐣屾噰妤犵偛顑夐幃娆撴偨閸涘鈧秹姊绘担鍛婃儓闁哥噥鍋婂畷鎰亹閹烘垹锛涢梺鍝勭▉閸樿偐鐥閺屾盯顢曢敐鍥舵殹濠电偛鎳庡Λ婵嬪蓟濞戞埃鍋撻敐搴′壕闁兼澘娼￠弻鐔碱敊閺傘倛鈧潡鏌熼鐣屾噰婵☆偄鍟埥澶娢旈埀顒勊夊鑸碘拻濞达絿鐡旈崵娆撴倵閸偄娴€规洘濞婇弫鎰緞婵犲嫮鏆繝寰锋澘鈧劙宕戦幘缁樼厓闁芥ê顦藉Σ鎼佹煃鐠囨煡顎楅摶锝嗙箾閼奸鍤欓柟顔肩墢缁辨捇宕掑顑藉亾瀹勬噴褰掑炊閵婏絼绮撻梺褰掓？閻掞箓宕戦敓鐘崇厓閺夌偞濯介崗宀勬煛閸☆厾鐣甸柡灞炬礃瀵板嫰宕煎┑鍡椥ら梻浣告啞閼归箖顢栨径鎰摕?闂傚倸鍊搁崐鎼佸磹閻戣姤鍤勯柛鎾茬閸ㄦ繃銇勯弽顐杭闁逞屽墮閸熸潙鐣烽妸褉鍋撳☉娅亝绂嶆潏銊х瘈闁汇垽娼у瓭闂佺顑呴敃顏堝箠閹捐鍨傛い鏃€鑹剧紞濠囧箖閳╁啯鍎熼柨婵嗘閸犳牠姊绘担鍛婃儓闁瑰嘲顑夊畷婊冣枎閹绢垪鍋撻敃鍌氶敜婵°倓绀佸▓婵嬫⒑濮瑰洤鐏柛瀣剁秮閸┾偓妞ゆ帊绀佺粭褏绱掓潏銊ユ诞闁糕斁鍋撳銈嗗笂閼冲墎绮诲▎鎰箚婵°倓绀佺欢?闂傚倸鍊搁崐宄懊归崶褏鏆﹂柣銏㈩焾绾惧鏌ｉ幇顔芥毄闁活厽鐟╅弻鐔告綇妤ｅ啯顎嶉梺绋垮濡啴寮婚妶鍚ゅ湱鈧綆鍋呴悵鏍磼閻愵剙绀冩俊顐㈠閳ワ妇鎹勯妸锕€纾繛鎾村嚬閸ㄤ即宕滄潏銊х閻庢稒锚濞堢娀鏌涙繝鍐⒈闁瑰箍鍨归埥澶愬閻樻鍚呮繝鐢靛█濞佳囨偋閻愬灚顫曢柣鎰棘閺冨牊鍋愰梻鍫熺◥閺夘參姊洪幖鐐插婵☆偄瀚伴敐鐐剁疀閹句焦妞介、鏂款吋閸℃ɑ鐝栭梻鍌欑窔濞佳呮崲閸℃稑鐤炬繝濠傚暞濮ｅ嫰姊婚崒姘偓鐑芥嚄閸洖鍌ㄧ憸鏃堝箖濡警娼╅悹鍝勬惈閻庮參鎮峰鍛暭閻㈩垱甯炵划濠氬冀椤撶喓鍘告繝銏ｆ硾鐎涒晝娑甸崼鏇熺厸闁糕剝顨嗛ˉ銏ゆ煛鐏炵晫啸妞ぱ傜窔閺屾盯骞樼€靛憡鍣伴梺绯曟杺閸ㄥ綊顢樻總绋块唶妞ゆ劧鍙婇埡鍌欑箚?+ 闂傚倸鍊峰ù鍥敋瑜庨〃銉╁传閵壯咁槸婵犵數濮撮崑鍡涙倿娴犲鐓犲┑顔藉姇閳ь剚顨堟竟鏇㈡嚍閵夛箑寮垮┑鈽嗗灡鐎笛呮兜妤ｅ啯鐓熼柕鍫濐槺閻ｆ椽鏌＄仦鍓ф创妤犵偞锕㈤幊鐘垫崉閸濆嫬鑵愰梻鍌欑閹诧繝銆冮崱妤冩殕闁归棿绀侀拑鐔兼煃閵夛箑澧柛姘儔閺屾盯骞囬埡浣割瀳濡炪値鍓欓ˇ闈涱潖濞差亝瀵犲璺号堥崑鎾诲箹娓氬洦鏅炴繝銏ｅ煐閸旀洟鎷?*/
    private static void drawModTree(GuiContext ctx, ConfigScreenState state) {
        ConfigLayout layout = state.layout;

        for (int i = 0; i < state.treeRows.size(); i++) {
            ConfigScreenState.TreeRow row = state.treeRows.get(i);

            // 涓€涓ā缁勶紙鍚嶇О + 鍏?tab锛変綔涓轰竴涓暣浣撴锛屼笉鍚屾ā缁勪箣闂寸暀绌洪湶鍑烘父鎴忚儗鏅€?
            if (!row.tab()) {
                int lastY = row.y() + row.h();
                for (int j = i + 1; j < state.treeRows.size(); j++) {
                    ConfigScreenState.TreeRow next = state.treeRows.get(j);
                    if (!next.tab()) {
                        break;
                    }
                    lastY = next.y() + next.h();
                }

                int boxY = row.y();
                int boxH = lastY - row.y();
                int clipTop = Math.max(boxY, layout.navY);
                int clipBottom = Math.min(boxY + boxH, layout.listY + layout.listH + 6);
                if (clipTop < clipBottom) {
                    UiTheme.fill(ctx, layout.sidebarX + 1, clipTop, layout.sidebarW,
                            clipBottom - clipTop, 0x66000000);
                }
            }

            int x = row.x();
            int y = row.y();
            int w = row.w();
            int h = row.h();

            if (y + h <= layout.navY || y >= layout.listY + layout.listH + 6) {
                continue;
            }

            int drawTop = Math.max(y, layout.navY);
            int drawBottom = Math.min(y + h, layout.listY + layout.listH + 6);

            if (row.tab()) {
                if (row.selected() && drawBottom > drawTop) {
                    UiTheme.fill(ctx, layout.sidebarX + 1, drawTop, layout.sidebarW, drawBottom - drawTop, 0x22000000);
                    UiTheme.fill(ctx, layout.sidebarX + 1, drawTop, 3, drawBottom - drawTop, UiTheme.TEXT_ACCENT);
                }

                if (y >= layout.navY - 2 && y + h <= layout.listY + layout.listH + 6) {
                    UiTheme.text(ctx, row.name(), x + 8, y + (h - 8) / 2,
                            row.selected() ? UiTheme.TEXT_TITLE : 0xFFC0C0C0, row.selected());
                }
            } else {
                if (drawBottom > drawTop) {
                    UiTheme.fill(ctx, layout.sidebarX + 1, drawTop, layout.sidebarW, drawBottom - drawTop,
                            row.selected() ? 0xA0000000 : 0x80000000);
                }

                if (row.selected() && drawBottom > drawTop) {
                    UiTheme.fill(ctx, layout.sidebarX + 1, drawTop, 3, drawBottom - drawTop, UiTheme.TEXT_ACCENT);
                }

                if (y >= layout.navY - 2 && y + 12 <= layout.listY + layout.listH + 6) {
                    UiTheme.text(ctx, row.name(), x + 8, y + 3,
                            row.selected() ? UiTheme.TEXT_TITLE : 0xFFC0C0C0, row.selected());

                    if (!row.version().isEmpty()) {
                        UiTheme.text(ctx, UiTheme.trim(ctx.fontRenderer(), row.version(), layout.navW - 30),
                                x + 8, y + 12, 0xFF7A7A7A, false);
                    }
                }
            }
        }

        int viewTop = layout.navY;
        int viewBottom = layout.listY + layout.listH + 6;
        int viewH = Math.max(1, viewBottom - viewTop);
        int barX = layout.sidebarX + layout.sidebarW + 2;
        UiTheme.fill(ctx, barX, viewTop, 8, viewH, 0x44000000);
        UiTheme.outline(ctx, barX, viewTop, 8, viewH, 0x88FFFFFF);

        if (state.treeContentH > viewH + 40) {
            int thumbH = Math.max(24, viewH * viewH / state.treeContentH);
            int maxScroll = Math.max(1, state.treeContentH - viewH);
            int thumbY = viewTop + (viewH - thumbH) * Math.min(state.treeScroll, maxScroll) / maxScroll;
            UiTheme.fill(ctx, barX + 1, thumbY, 6, thumbH, 0xFFFFFFFF);
        }
    }

    /** 濠电姷鏁告慨鐢割敊閺嶎厼绐楁俊銈傚亾闁伙絿鍏樺畷绋课旈埀顒€顔忓┑鍥ヤ簻闁圭偓鍓氬褏绱撳鍕獢鐎殿喖顭烽弫鎰緞婵犲倸鏁ら梻浣圭湽閸ㄥ寮灞稿徍闂備浇顕у锕傦綖婢跺⊕鍝勵煥閸繄顦у┑鈽嗗灥椤斿﹦鎹㈤崱娑欑厵闂傚倸顕ˇ锕傚船椤栫偞鈷戦梻鍫熺〒婢ф洘绻涢弶鎴濃偓鍨暦椤掑嫭顥堟繛鎴炲笚閺傗偓闂備胶绮崝鏇㈡偤閵娧傜剨濞寸厧鐡ㄩ悡鐔兼煏婵犲繐顩柣顓熷笧閳ь剝顫夊ú婊堝窗閺嶎厹鈧礁顫滈埀顒勫箖濞嗘挻顥堟繛鎴烆焽椤╂挳姊婚崒姘偓鎼佸磹妞嬪海鐭嗗〒姘ｅ亾妤犵偛顦甸弫鎾绘偐閸愯弓缃曢梻浣告惈濞层垽宕归崷顓犱笉閻熸瑥瀚ㄦ禍婊堟煙閺夎法鍩ｆ俊缁㈠櫍閺屾稓鈧綆浜滈埀顒€婀遍幑銏犫槈閵忕姴鑰垮┑掳鍊撻懗鍫曘€呮导瀛樷拺缂備焦蓱鐏忣亪鏌涙惔銏㈠弨妤犵偛鐗撴俊鎼佸Ψ椤旇棄缂撻梻浣虹《閸撴繈銆冮崨杈剧稏闁冲搫鎳忛崑鐘虫叏濡搫鑸归柡瀣⊕閹便劍绻濋崘鈹夸虎閻庤娲﹂崑濠傜暦閻旂⒈鏁冮柨婵嗘－閸熷牓姊婚崒娆掑厡缁绢厼鐖煎鎻掝煥閸喎浜卞┑鐘诧工閻楀棛绮堥崱娑欑厵闁绘垶锕╁▓鏃傜磼閻樼數甯涢柕鍥у瀵噣宕惰濮规顪冮妶蹇撶槣闁革綇绲介～蹇撁洪鍜佹濠电偞鍨兼禍顒勫矗濮橆厾绡€缁剧増菤閸嬫捇鎼归銏＄亷闁诲氦顫夊ú妯侯渻娴犲宓侀柛銉墯閸嬪鏌涢鐘茬仼鐎殿喛娅曠换婵嬫偨闂堟稐娌梺鎼炲妼閻栧ジ鍨鹃敃鍌氱倞妞ゆ帊绀侀埀顒€娼￠弻锝夊箣閿濆憛鎾绘煟閹惧啿鏆熼柟鑼焾椤劑宕煎┑鍫Ф婵犵數鍋涘Λ娆撳礉濡ゅ懏鈷旈柛鏇ㄥ灡閻撴盯鏌涢幇鈺佸闁逞屽墲瀹曠數鍒掓繝姘婵炲棗澧介崬鐢告⒑閸忓吋鍊愭繛浣冲嫭鍙忛柛銉墯閻撴洘绻涢崱妤呯崪闁衡偓婵犳碍鐓忛柛銉戝喚浼冮悗娈垮枙缁瑦淇婇幖浣肝╅柕澶樺枟椤ャ倝姊婚崒娆愮グ妞ゆ泦鍕垫闁归棿绀佸洿闂佸綊妫跨粈渚€鎷?TAB闂?*/
    public static boolean onTreeScroll(GuiBase screen, double mouseX, double mouseY, double vertical) {
        if (is26x() || !hasLayout(screen)) {
            return false;
        }

        ConfigScreenState state = stateFor(screen);
        ConfigLayout layout = state.layout;

        if (mouseX < layout.sidebarX || mouseX > layout.sidebarX + layout.sidebarW ||
                mouseY < layout.sidebarY || mouseY > layout.sidebarY + layout.sidebarH) {
            return false;
        }

        int viewH = layout.listH;
        int max = Math.max(0, state.treeContentH - viewH);

        state.treeScroll = Math.max(0, Math.min(max,
                state.treeScroll - (int) Math.signum(vertical) * 20));
        TREE_SCROLL = state.treeScroll;

        return true;
    }

    /** 閹锋牕濮╁姘З閺夆剝妞傞幐澶愮炊閺嶅洤顤冮柌蹇旀纯閺傞缍呯純顔衡偓?*/
    public static boolean onTreeScrollbarDrag(GuiBase screen, double dragY) {
        if (!treeBarDragging || is26x() || !hasLayout(screen)) {
            return false;
        }

        ConfigScreenState state = stateFor(screen);
        ConfigLayout layout = state.layout;
        int viewH = Math.max(1, layout.listH);
        int max = Math.max(0, state.treeContentH - viewH);
        int thumbH = Math.max(24, viewH * viewH / Math.max(state.treeContentH, viewH));
        int travel = Math.max(1, viewH - thumbH);
        state.treeScroll = Math.max(0, Math.min(max,
                state.treeScroll + (int) Math.round(dragY * max / travel)));
        TREE_SCROLL = state.treeScroll;

        return true;
    }

    /** 閻愮懓鍤?閹锋牕濮╁锔挎櫠濠婃艾濮╅弶鈩冩閻╁瓨甯寸捄鍐插煂鐎电懓绨叉担宥囩枂閵?*/
    public static boolean onSearchChar(GuiBase screen, int codepoint) {
        ConfigScreenState state = STATES.get(screen);

        if (state == null || state.searchField == null || !state.searchActive) {
            return false;
        }

        if (codepoint < 32 || codepoint == 127) {
            return false;
        }

        String text = state.searchField.getValue();

        if (text.length() < 64) {
            state.searchField.setValue(text + new String(Character.toChars(codepoint)));
            state.searchQuery = state.searchField.getValue();
        }

        return true;
    }

    public static boolean onSearchKey(GuiBase screen, int keyCode) {
        ConfigScreenState state = STATES.get(screen);

        if (state == null || state.searchField == null) {
            return false;
        }

        if (keyCode == 256) { // GLFW_KEY_ESCAPE
            if (state.searchActive) {
                // 绗竴娆?Esc 鍙€€鍑烘悳绱㈣緭鍏ワ紝鍐嶆寜涓€娆℃墠鍏抽棴鐣岄潰銆?
                state.searchField.setFocused(false);
                state.searchActive = false;
            } else {
                screen.onClose();
            }
            return true;
        }

        if (!state.searchActive) {
            return false;
        }

        if (keyCode == 259) { // GLFW_KEY_BACKSPACE
            String text = state.searchField.getValue();

            if (!text.isEmpty()) {
                state.searchField.setValue(text.substring(0, text.length() - 1));
                state.searchQuery = state.searchField.getValue();
            }

            return true;
        }

        if (keyCode == 257) { // GLFW_KEY_ENTER
            state.searchActive = false;
            state.searchField.setFocused(false);
            return true;
        }

        return false;
    }

    public static void onSearchBlur(GuiBase screen) {
        ConfigScreenState state = STATES.get(screen);

        if (state != null) {
            state.searchActive = false;
        }
    }

    /** 閻愮懓鍤い鑸电埉閹兼粎鍌ㄥ鍡樻閿涘本濡告潏鎾冲弳閻掞妇鍋ｆ禒搴″灙鐞涖劌鍞撮幖婊呭偍濡楀棜娴嗛崚浼淬€婇弽蹇嬧偓?*/
    public static boolean onSearchClick(GuiBase screen, double mouseX, double mouseY) {
        ConfigScreenState state = STATES.get(screen);

        if (state == null || state.searchField == null) {
            return false;
        }

        GuiTextFieldGeneric field = state.searchField;
        ConfigLayout layout = state.layout;

        // 妞よ埖鐖幖婊呭偍閸栧搫鐓欓弫纾嬵攽閸欘垳鍋ｉ敍宀勪缉閸忓秵鏋冪€涙顢嬮崘鍛村劥閸ф劖鐖ｉ崑蹇撴▕鐎佃壈鍤ч悙閫涚瑝娑擃厹鈧?
        // 右上角切换器优先：不要被搜索热区吃掉点击。
        for (WidgetBase widget : ((GuiBaseAccessor) screen).malilibui$getWidgets()) {
            if (widget instanceof WidgetDropDownList<?> && widget.isMouseOver((int) mouseX, (int) mouseY)) {
                field.setFocused(false);
                state.searchActive = false;
                return false;
            }
        }

        boolean inTopBar = mouseX >= field.getX() - 2 && mouseX <= field.getX() + field.getWidth() + 2 &&
                mouseY >= field.getY() - 2 && mouseY <= field.getY() + field.getHeight() + 2;

        if (!inTopBar) {
            // 鐐瑰嚮鍒閫€鍑烘悳绱㈣緭鍏ワ紝浣嗘妸鐐瑰嚮缁х画浜ょ粰涓嬮潰鐨勬帶浠躲€?
            field.setFocused(false);
            state.searchActive = false;
            return false;
        }

        for (fi.dy.masa.malilib.gui.wrappers.TextFieldWrapper<? extends GuiTextFieldGeneric> wrapper :
                ((GuiBaseAccessor) screen).malilibui$getTextFields()) {
            wrapper.setFocused(false);
        }

        if (screen instanceof fi.dy.masa.malilib.gui.GuiListBase<?, ?, ?> listBase) {
            fi.dy.masa.malilib.gui.widgets.WidgetListBase<?, ?> listWidget =
                    ((com.github.bunnyi116.malilibui.mixin.accessor.GuiListBaseAccessor) listBase)
                            .malilibui$getListWidget();
            fi.dy.masa.malilib.gui.widgets.WidgetSearchBar searchBar =
                    listWidget == null ? null : listWidget.getSearchBarWidget();

            if (searchBar != null) {
                ((com.github.bunnyi116.malilibui.mixin.accessor.WidgetSearchBarAccessor) searchBar)
                        .malilibui$getSearchBox().setFocused(false);
            }
        }

        field.setFocused(true);
        state.searchActive = true;
        return true;
    }

    public static boolean onTreeScrollbarClick(GuiBase screen, double mouseX, double mouseY) {
        treeBarDragging = false;
        if (is26x() || !hasLayout(screen)) {
            return false;
        }

        ConfigScreenState state = stateFor(screen);
        ConfigLayout layout = state.layout;
        int barX = layout.sidebarX + layout.sidebarW + 2;

        if (mouseX < barX || mouseX > barX + 8) {
            return false;
        }

        int viewTop = layout.navY;
        int viewH = layout.listH;
        int max = Math.max(0, state.treeContentH - viewH);

        if (max <= 0 || mouseY < viewTop || mouseY > viewTop + viewH) {
            return false;
        }

        treeBarDragging = true;
        int thumbH = Math.max(24, viewH * viewH / Math.max(state.treeContentH, viewH));
        int travel = Math.max(1, viewH - thumbH);
        int rel = Math.max(0, Math.min(travel, (int) mouseY - viewTop - thumbH / 2));
        state.treeScroll = rel * max / travel;
        TREE_SCROLL = state.treeScroll;

        return true;
    }

    private static int layoutAccentX(int rowX) {
        return rowX + 1;
    }

